#include <iostream>
#include <string>
struct Thing {
  std::string data;
  Thing(const std::string& d) : data(d) { std::cout << "Thing constructed: " << data << std::endl; }
  Thing(Thing&& other) noexcept : data(std::move(other.data)) { std::cout << "Thing move-constructed: " << data << std::endl; }
  Thing(const Thing& other) : data(other.data) { std::cout << "Thing copy-constructed: " << data << std::endl; }
  ~Thing() { std::cout << "Thing destructed: " << data << std::endl; }
};
Thing f(bool b) {
  Thing t("Hello");
  if (b) {
    throw t; // Exception handling might prevent RVO/NRVO
  }
  return t; 
}
int main() {
  Thing t1 = f(false);
  Thing t2 = f(true); //Exception prevents optimization here likely.
  return 0;
}
